const simRealEquity = (hands, board, gameType) => {
  try {
    const iters = (gameType || '').startsWith('Omaha') ? 120 : 260;
    const res = {};
    hands.forEach(h => res[h.uid] = 0);
    const known = [...board];
    hands.forEach(h => known.push(...h.cards));
    for (let i = 0; i < iters; i++) {
      const deck = deckWithout(known);
      const fb = [...board];
      while (fb.length < 5) fb.push(deck.pop());
      let best = -1,
        winners = [];
      hands.forEach(h => {
        const s = bestScoreFull(h.cards, fb, gameType);
        if (s > best) {
          best = s;
          winners = [h.uid];
        } else if (s === best) winners.push(h.uid);
      });
      winners.forEach(u => res[u] += 1 / winners.length);
    }
    Object.keys(res).forEach(u => res[u] = Math.round(res[u] / iters * 100));
    return res;
  } catch (e) {
    return null;
  }
};
